        q: { ja: "AIが年間$500,000の人件費を削減。10x rule（価値≥価格の10倍）に従う年額上限は。", en: "AI saves $500,000/yr in labor. Under the 10x rule (value ≥10× price), max annual price?" },
        sol: { ja: "価値≥価格×10 → 価格≤価値/10\n価格上限＝500,000/10＝$50,000/年\n答え: 年$50,000（上限目安）", en: "Value ≥ 10×price → price ≤ value/10\nMax price = 500,000/10 = $50,000/yr\nAnswer: ~$50,000/yr (ceiling)" },
